<script setup>
import {computed,nextTick,ref} from 'vue'
import {optimizationExamples,optimizationExample,walkthroughSteps as steps} from '../learning-example.js'
import WorkspaceIcon from './WorkspaceIcon.vue'
import RerankPrinciple from './RerankPrinciple.vue'
const props=defineProps({busy:Boolean,resume:Boolean,methodId:{type:String,default:'RERANK_TOGGLE'}})
const emit=defineEmits(['practice','experiment','update:methodId'])
const step=ref(0),heading=ref(null)
const example=computed(()=>optimizationExample(props.methodId))
async function go(index){step.value=index;await nextTick();heading.value?.focus({preventScroll:true});heading.value?.scrollIntoView({block:'start',behavior:'smooth'})}
function choose(id){emit('update:methodId',id);step.value=0}
</script>
<template>
 <section class="panel learning-walkthrough" aria-label="完整评测示范">
  <header class="walkthrough-intro"><h2 v-if="resume">五种改法，先看问题在哪</h2><p class="walkthrough-notice">预设教学示例 · 不需要 Key，不调用模型，不代表真实评测结果。</p></header>
  <nav class="walkthrough-methods" aria-label="五种改法"><button v-for="item in optimizationExamples" :key="item.id" type="button" :aria-pressed="example.id===item.id" @click="choose(item.id)"><WorkspaceIcon :name="item.icon" :size="24" /><strong>{{item.title}}</strong><small>{{item.short}}</small></button></nav>
  <nav class="walkthrough-steps" aria-label="示范步骤"><button v-for="(label,index) in steps" :key="label" type="button" :aria-current="step===index?'step':undefined" :class="{active:step===index}" @click="go(index)"><span>{{index+1}}</span>{{label}}</button></nav>
  <div class="walkthrough-body" :data-method="example.id">
   <div class="walkthrough-current"><WorkspaceIcon :name="example.icon" :size="18" /><strong>{{example.title}}</strong><span>{{step+1}} / {{steps.length}}</span></div>
   <h3 ref="heading" tabindex="-1">{{['先看这道题与本轮资料','证据支持先试哪种修改？','这次只改一项','用原题复测，也看有没有变差','是否保留本次修改？'][step]}}</h3>
   <template v-if="step===0">
    <div class="walkthrough-context"><article><span class="walkthrough-art"><WorkspaceIcon name="document" :size="26" /></span><div><small>用于核对的参考规则</small><p>{{example.policy}}</p></div></article><article><span class="walkthrough-art"><WorkspaceIcon name="search" :size="26" /></span><div><small>本轮检索情况</small><p>{{example.evidence}}</p></div></article></div>
    <div class="walkthrough-conversation"><div><small>顾客问</small><p>{{example.question}}</p></div><div class="walkthrough-agent"><small>Agent 原回答</small><p>{{example.before}}</p></div></div>
    <p class="walkthrough-takeaway"><WorkspaceIcon name="help" :size="18" /><span>先核对记录、参考规则和判错理由，确认问题后再选改法。</span></p>
   </template>
   <template v-else-if="step===1">
    <ol class="walkthrough-diagnosis"><li v-for="(item,index) in example.diagnosis" :key="item.name"><span>{{index+1}}</span><div><strong>{{item.name}}</strong><p>{{item.detail}}</p></div></li></ol>
    <div class="walkthrough-cause"><WorkspaceIcon :name="example.icon" :size="25" /><div><small>本例先试 · {{example.title}}</small><p>{{example.cause}}</p></div></div>
    <p class="walkthrough-takeaway"><WorkspaceIcon name="alert" :size="18" /><span>{{example.notFor}}</span></p>
   </template>
   <template v-else-if="step===2">
    <RerankPrinciple v-if="example.id==='RERANK_TOGGLE'" :example="example" />
    <div v-else class="walkthrough-change-flow"><article><h4>{{example.beforeLabel}}</h4><ul><li v-for="(item,index) in example.beforeItems" :key="item.text" :class="{'is-used':item.used,'is-relevant':item.relevant}"><span v-if="['RERANK_TOGGLE','TOP_K_CHANGE'].includes(example.id)" class="item-rank">{{index+1}}</span><WorkspaceIcon v-else :name="example.icon" :size="17" /><span>{{item.text}}</span><small v-if="['RERANK_TOGGLE','TOP_K_CHANGE'].includes(example.id)">{{item.relevant?'关键 · ':''}}{{item.used?'已提供':'未提供'}}</small><small v-else-if="item.relevant">关键</small></li></ul></article><WorkspaceIcon class="walkthrough-change-arrow" name="arrow" :size="25" /><article class="walkthrough-new"><h4>{{example.afterLabel}}</h4><ul><li v-for="(item,index) in example.afterItems" :key="item.text" :class="{'is-used':item.used,'is-relevant':item.relevant}"><span v-if="['RERANK_TOGGLE','TOP_K_CHANGE'].includes(example.id)" class="item-rank">{{index+1}}</span><WorkspaceIcon v-else :name="example.icon" :size="17" /><span>{{item.text}}</span><small v-if="['RERANK_TOGGLE','TOP_K_CHANGE'].includes(example.id)">{{item.relevant?'关键 · ':''}}{{item.used?'已提供':'未提供'}}</small><small v-else-if="item.relevant">关键</small></li></ul></article></div>
    <p class="walkthrough-fixed"><WorkspaceIcon name="prepare" :size="17" />{{example.fixed}}</p>
    <div class="walkthrough-prediction"><div><small>希望看到</small><p>{{example.prediction}}</p></div><div><small>也要检查</small><p>{{example.potentialCost}}</p></div></div>
   </template>
   <template v-else-if="step===3">
    <div class="walkthrough-answer"><WorkspaceIcon name="chat" :size="25" /><div><small>目标题 · 修改后的预设回答</small><p>{{example.after}}</p></div></div>
    <div class="walkthrough-comparisons" role="list" aria-label="三道题的示例对比"><article v-for="row in example.comparisons" :key="row.question" role="listitem"><div class="comparison-heading"><strong>{{row.question}}</strong><span :class="['comparison-status',row.state]">{{row.afterState}}</span></div><div class="walkthrough-comparison-pair"><div><small>改前 · {{row.beforeState}}</small><p>{{row.before}}</p></div><WorkspaceIcon name="arrow" :size="18" /><div><small>改后</small><p>{{row.after}}</p></div></div></article></div>
    <p class="walkthrough-takeaway"><WorkspaceIcon name="compare" :size="19" /><span>逐题检查改善、退化与未解决。缺资料或仍需追问的题，不能算成已经解决。</span></p>
   </template>
   <template v-else>
    <dl class="walkthrough-record"><div><dt>本次改法</dt><dd><WorkspaceIcon :name="example.icon" :size="21" />{{example.title}}</dd></div><div><dt>是否保留</dt><dd>{{example.decision}}</dd></div><div><dt>依据</dt><dd>{{example.reason}}</dd></div><div><dt>还要验证</dt><dd>{{example.limitations}}</dd></div></dl>
    <p class="walkthrough-takeaway"><WorkspaceIcon name="check" :size="18" /><span>每种改法都要检查整批原题。目标题改善，也可以因为其他题退化而不保留。</span></p>
    <div class="walkthrough-next"><button type="button" class="primary" :disabled="busy" @click="emit('experiment')">到我的实验查看真实结果 →</button><button type="button" class="text-button" :disabled="busy" @click="emit('practice')">{{resume?'回到正在做的题 →':'继续证据判断练习 →'}}</button></div>
    <p class="walkthrough-notice">上方示范不会保存成实验。证据判断练习还会检查记录与评分是否有误；与这五种 Agent 改法分别说明。</p>
   </template>
  </div>
  <footer class="walkthrough-controls"><button type="button" class="text-button" :disabled="step===0" @click="go(step-1)">← 上一步</button><button v-if="step<steps.length-1" type="button" class="primary" @click="go(step+1)">下一步：{{steps[step+1]}} →</button><button v-else type="button" class="text-button" @click="go(0)">从头再看一遍</button></footer>
 </section>
</template>
<style scoped>
