gin:0;padding:0;display:grid;gap:8px}.walkthrough-change-flow li{display:flex;align-items:center;gap:9px;padding:10px;background:var(--color-canvas);border:1px solid transparent;border-radius:6px;font-size:13px;line-height:1.8;color:var(--muted)}.walkthrough-change-flow li>span:not(.item-rank){min-width:0;overflow-wrap:anywhere}.walkthrough-change-flow li.is-used{border-color:var(--border);color:var(--color-text)}.walkthrough-change-flow li.is-relevant{background:#eaf0e1;border-color:#a0b18f;color:#506341}.walkthrough-change-flow li>small{margin-left:auto;white-space:nowrap;font-size:9px}.item-rank{font-size:11px;color:var(--muted);width:14px;flex-shrink:0}.walkthrough-change-arrow{color:#a6af9b}.walkthrough-new{background:#f9fbf6}.walkthrough-fixed{display:flex;align-items:flex-start;gap:9px;font-size:12px!important;color:var(--muted);margin:18px 0}.walkthrough-fixed svg{flex-shrink:0;margin-top:3px}.walkthrough-prediction{display:grid;grid-template-columns:1fr 1fr;gap:18px;border-top:1px solid var(--border);padding-top:16px}.walkthrough-prediction p{font-size:13px;margin-top:6px}.walkthrough-answer{display:flex;align-items:flex-start;gap:13px;padding:16px;background:#eef3e7;border-radius:9px}.walkthrough-answer>svg{color:#7f8f6c;flex-shrink:0;margin-top:5px}.walkthrough-answer p{margin-top:5px}.walkthrough-comparisons{margin:12px 0}.walkthrough-comparisons>article{padding:17px 0;border-bottom:1px solid var(--border)}.comparison-heading{display:flex;align-items:center;justify-content:space-between;gap:14px;font-size:13px}.comparison-status{font-size:10px;color:var(--muted);white-space:nowrap}.comparison-status.improved,.comparison-status.pass{color:var(--color-success)}.comparison-status.regressed{color:var(--color-danger)}.comparison-status.pending{color:var(--color-warning)}.walkthrough-comparison-pair{display:grid;grid-template-columns:1fr 18px 1fr;gap:14px;align-items:center;margin-top:10px}.walkthrough-comparison-pair>svg{color:#a6af9b}.walkthrough-comparison-